"""Copy every disbursement from the Meridian Disbursements API (v2) into disbursements.jsonl."""
import argparse
import json
import urllib.error
import urllib.parse
import urllib.request


def _get_json(url, timeout):
    with urllib.request.urlopen(url, timeout=timeout) as resp:
        return json.load(resp)


def _post_json(url, body, timeout):
    req = urllib.request.Request(
        url,
        data=json.dumps(body).encode(),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.load(resp)


def fetch_disbursements(base_url, limit=100, timeout=30):
    """Walk the v2 export one window at a time until it is drained.

    Windows overlap at their edges, so disbursements are deduplicated on id
    while preserving creation order. A malformed or expired cursor restarts
    the export from the beginning, per the Meridian developer guide.
    """
    disbursements = []
    seen = set()
    cursor = None
    while True:
        url = f"{base_url}/v2/disbursements?limit={limit}"
        if cursor is not None:
            url += f"&cursor={urllib.parse.quote(cursor, safe='')}"
        try:
            page = _get_json(url, timeout)
        except urllib.error.HTTPError as e:
            if e.code == 400:
                try:
                    err = json.load(e)
                except ValueError:
                    err = {}
                if err.get("error") == "invalid_cursor":
                    # Cursor is malformed or expired: restart the export.
                    disbursements, seen, cursor = [], set(), None
                    continue
            raise
        for d in page["disbursements"]:
            if d["id"] not in seen:
                seen.add(d["id"])
                disbursements.append(d)
        if page["drained"]:
            return disbursements
        cursor = page["cursor"]


def verify_disbursements(base_url, disbursements, timeout=30):
    """Ask the v2 server whether the sync delivered every disbursement exactly once."""
    return _post_json(f"{base_url}/v2/verify", {"disbursements": disbursements}, timeout)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="disbursements.jsonl")
    ap.add_argument("--limit", type=int, default=100, help="window size, 1 to 100 (default 100)")
    ap.add_argument(
        "--verify",
        action="store_true",
        help="POST the sync to /v2/verify and fail unless every disbursement was delivered exactly once",
    )
    args = ap.parse_args()
    if not 1 <= args.limit <= 100:
        ap.error("--limit must be between 1 and 100")
    base_url = args.base_url.rstrip("/")
    disbursements = fetch_disbursements(base_url, limit=args.limit)
    with open(args.out, "w") as f:
        for d in disbursements:
            f.write(json.dumps(d) + "\n")
    print(f"synced {len(disbursements)} disbursements")
    if args.verify:
        result = verify_disbursements(base_url, disbursements)
        print(json.dumps(result))
        if not result.get("each_once"):
            raise SystemExit("verification failed: not every disbursement delivered exactly once")


if __name__ == "__main__":
    main()

